"""Hand-specified examples and boundary contracts, not expected values generated by the rule."""
import ast
import copy
from dataclasses import replace
from pathlib import Path
import unittest
from buy_exhaustion import BuyExhaustionEngine,Observation,Quote,evaluate_buy_exhaustion

class BuyExhaustionContractTest(unittest.TestCase):
    def observation(self,**overrides):
        known=Observation(100000,0,44,255,0,685,50,100000,
                          Quote(100000,18638,18640),Quote(90000,18641,18644),10000)
        return replace(known,**overrides)

    def test_morning_manual_example(self):
        result=evaluate_buy_exhaustion(self.observation())
        self.assertTrue(result['alert'])
        self.assertEqual(result['status'],'BUY_WEAKENING')
        self.assertAlmostEqual(result['buy_ratio'],0.19270072992700732)
        self.assertAlmostEqual(result['sell_share'],0.8528428093645485)
        self.assertEqual(result['midpoint_change_points'],-0.35)
        self.assertEqual(result['bid_change_points'],-0.3)
        self.assertEqual(result['ask_change_points'],-0.4)

    def test_buy_ratio_equal_half_is_not_below_half(self):
        r=evaluate_buy_exhaustion(self.observation(buy=10,sell=100,baseline_buy=60))
        self.assertEqual(r['buy_ratio'],0.5)
        self.assertTrue(r['eligible']);self.assertFalse(r['alert'])
        self.assertFalse(r['conditions']['buy_rate_falls'])

    def test_sell_share_equal_65_percent_is_not_above(self):
        r=evaluate_buy_exhaustion(self.observation(buy=35,sell=65,baseline_buy=500))
        self.assertEqual(r['sell_share'],0.65)
        self.assertTrue(r['eligible']);self.assertFalse(r['alert'])

    def test_exact_one_tick_mid_drop_is_enough_but_both_sides_must_fall(self):
        exact=self.observation(quote_now=Quote(100000,99,101),quote_before=Quote(90000,100,102))
        self.assertTrue(evaluate_buy_exhaustion(exact)['alert'])
        only_ask=self.observation(quote_now=Quote(100000,100,102),quote_before=Quote(90000,100,104))
        r=evaluate_buy_exhaustion(only_ask)
        self.assertEqual(r['midpoint_change_points'],-0.1)
        self.assertFalse(r['alert']);self.assertFalse(r['conditions']['both_quotes_fall'])

    def test_no_buy_now_can_be_valid_but_no_baseline_cannot(self):
        self.assertTrue(evaluate_buy_exhaustion(self.observation(buy=0))['alert'])
        r=evaluate_buy_exhaustion(self.observation(baseline_buy=0))
        self.assertIsNone(r['buy_ratio']);self.assertFalse(r['alert'])
        self.assertIn('zero_buy_baseline',r['issues'])

    def test_quality_edges(self):
        self.assertTrue(evaluate_buy_exhaustion(self.observation(first_event_ts=60000,covered_ms=8000,
            last_trade_ts=95000,quote_now=Quote(95000,18638,18640),quote_before=Quote(85000,18641,18644)))['alert'])
        for changed,reason in [({'first_event_ts':60001},'warmup'),({'covered_ms':7999},'quote_coverage'),
            ({'trade_count':19},'few_trades'),({'last_trade_ts':94999},'stale_trade'),
            ({'quote_now':Quote(94999,18638,18640)},'quote_now'),
            ({'quote_before':Quote(84999,18641,18644)},'quote_before'),
            ({'quote_now':Quote(100000,18640,18640)},'quote_now'),
            ({'buy':5,'sell':44},'low_classified_volume'),({'unknown':34},'unknown_side'),
            ({'quote_now':Quote(100001,18638,18640)},'quote_now')]:
            with self.subTest(reason=reason):
                r=evaluate_buy_exhaustion(self.observation(**changed))
                self.assertFalse(r['alert']);self.assertIn(reason,r['issues'])
        self.assertTrue(evaluate_buy_exhaustion(self.observation(buy=40,sell=230,unknown=30))['eligible'])

    def test_open_left_closed_right_windows_and_future_append(self):
        e=BuyExhaustionEngine()
        for t in range(0,40001,1000):e.push_quote(t,1000 if t<=30000 else 999,1002 if t<=30000 else 1001)
        e.push_trade(0,999,'BUY')  # excluded from (0,30000] baseline
        e.push_trade(1,30,'BUY');e.push_trade(30000,30,'BUY')
        e.push_trade(30001,10,'BUY');e.push_trade(40000,100,'SELL')
        result=e.evaluate(40000)
        self.assertEqual((result['buy_10s'],result['sell_10s'],result['baseline_buy_30s']),(10,100,60))
        self.assertEqual(result['covered_ms'],10000)
        before=copy.deepcopy(result)
        e.push_trade(50000,10000,'SELL');e.push_quote(50000,500,501)
        self.assertEqual(e.evaluate(40000),before)
        with self.assertRaises(ValueError):e.push_trade(49000,1,'BUY')
        with self.assertRaises(ValueError):e.push_quote(49000,500,501)

    def test_independent_oracle_has_no_formula_or_adapter_imports(self):
        tree=ast.parse(Path(__file__).with_name('verify_buy_exhaustion_raw.py').read_text())
        imports={n.module for n in ast.walk(tree) if isinstance(n,ast.ImportFrom)}
        imports|={a.name for n in ast.walk(tree) if isinstance(n,ast.Import) for a in n.names}
        self.assertFalse(imports & {'buy_exhaustion','flow_assessment','replay_server','backtest_buy_exhaustion'})

if __name__=='__main__':unittest.main()
